reddest_row.source:
def agent(grid):
    def how_red(i):
        return sum(cell.colour == "red" for cell in grid.rows[i])
    return [paint_row(max(range(grid.size), key=how_red), "red")]

guarded_row.source:
def agent(grid):
    if sum(cell.colour == "red" for cell in grid.rows[0]) >= 3:
        return [paint_row(0, "red")]
    return []

biggest_to_corner.source:
def agent(grid):
    big = max(grid.cells, key=lambda cell: cell.value)
    if (big.row, big.col) == (0, 0):
        return []
    return [swap_cells(grid.cell(0, 0), big)]
